Lemma zcells : forall m A cs,
  zshape cs = true ->
  (forall i, 0 <= i < Z.of_nat (cells_size cs) -> m (wa (A + i)) = Some (Z_to_bv 8 0)) ->
  wr_at asegs m A (Z.of_nat (cells_size cs)) ->
